class GeneratedProgramDispatchError(ValueError):
    """Frozen KDA dispatch evidence is incomplete, inconsistent, or tampered."""


def _canonical_sha256(value: object) -> str:
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def _object(value: object, fields: set[str], label: str) -> Mapping[str, object]:
    if not isinstance(value, Mapping) or set(value) != fields:
        actual = set(value) if isinstance(value, Mapping) else type(value).__name__
        raise GeneratedProgramDispatchError(
            f"{label} fields differ: expected {sorted(fields)!r}, got {actual!r}"
        )
    return value


def _nonempty_string(value: object, label: str) -> str:
    if not isinstance(value, str) or not value:
        raise GeneratedProgramDispatchError(f"{label} must be a non-empty string")
    return value


def _ordered_fields(value: object, label: str, *, scalar: bool = False, allow_empty: bool = False):
    if not isinstance(value, list) or (not value and not allow_empty):
        raise GeneratedProgramDispatchError(f"{label} must be an ordered list")
    result, names = [], set()
    for index, item in enumerate(value):
        field = _object(item, {"name", "dtype"}, f"{label}[{index}]")
        name = _nonempty_string(field["name"], f"{label}[{index}].name")
        dtype = _nonempty_string(field["dtype"], f"{label}[{index}].dtype")
        if name in names or (scalar and dtype not in _SCALAR_DTYPES):
            raise GeneratedProgramDispatchError(f"{label} contains an invalid field")
        names.add(name)
        result.append(field)
    return result


def _torch_dtype_name(value: Any) -> str:
    name = str(value.dtype).removeprefix("torch.")
    if not name:
        raise GeneratedProgramDispatchError("tensor dtype is unavailable")
    return name


def _tensor_contract(value: Any) -> dict[str, object]:
    return {
        "dtype": _torch_dtype_name(value),
        "shape": [int(dim) for dim in value.shape],
        "stride": [int(dim) for dim in value.stride()],
        "storage_offset": int(value.storage_offset()),
    }


def _storage_pointer(value: Any) -> int:
    return int(value.untyped_storage().data_ptr())


def _storage_span(contract):
    shape, stride, offset = contract["shape"], contract["stride"], contract["storage_offset"]
    if any(dim == 0 for dim in shape):
        return None
    lower = upper = int(offset)
    for dim, step in zip(shape, stride, strict=True):
        extent = (int(dim) - 1) * int(step)
        lower += min(0, extent)
        upper += max(0, extent)
    return lower, upper


def _tensor_content_sha256(value: Any) -> str:
    import torch
    contiguous = value.detach().contiguous().view(torch.uint8).cpu()
    payload = bytes(contiguous.flatten().tolist())
    digest = hashlib.sha256()
    digest.update(json.dumps(_tensor_contract(value), sort_keys=True, separators=(",", ":")).encode())
    digest.update(b"\0")
    digest.update(payload)
    return digest.hexdigest()


